type Key = keyof typeof strings.en;

/* printed sheets are always black on white (FormSheet); borders follow the text colour */
const sheetTable: CSSProperties = { width: '100%', borderCollapse: 'collapse', fontSize: 11, margin: '10px 0' };
const sheetCell: CSSProperties = { border: '1px solid currentColor', padding: '5px 7px', textAlign: 'left', verticalAlign: 'top' };
const sheetRow: CSSProperties = { display: 'flex', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap', fontSize: 12, marginBottom: 8 };
const signGrid: CSSProperties = { display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: 24, marginTop: 28, fontSize: 11 };
const signLine: CSSProperties = { borderTop: '1px solid currentColor', paddingTop: 4 };

const roleOf = (p: PortalId): Role => (p === 'tms' || p === 'smms' || p === 'tdms' ? p : 'control');

export default function FormsPage({ tab }: FormsPageProps) {
  const snapshot = useAppStore((s) => s.snapshot);
  const portal = usePortal();
  if (!snapshot) return <PlanPending />;
  return <Forms key={`${portal}:${tab ?? ''}`} snapshot={snapshot} role={roleOf(portal)} routeTab={tab} />;
}

function Forms({ snapshot, role, routeTab }: { snapshot: Snapshot; role: Role; routeTab?: FormsPageProps['tab'] }) {
  const t = useT(strings);
  const drawer = useDrawerParams();

  const user = useAppStore((s) => s.user);
  const approvals = useAppStore((s) => s.approvals);
  const forms = useAppStore((s) => s.forms);
  const tsrs = useAppStore((s) => s.tsrs);
  const powerBlocks = useAppStore((s) => s.powerBlocks);
  const executionLog = useAppStore((s) => s.executionLog);
  const setFormStatus = useAppStore((s) => s.setFormStatus);
  const updateTsr = useAppStore((s) => s.updateTsr);
  const setPowerBlock = useAppStore((s) => s.setPowerBlock);
  const notify = useAppStore((s) => s.notify);
  const toast = useAppStore((s) => s.toast);

  const corridor = snapshot.corridor;
  const tabs = TABS[role];
  const [tab, setTab] = useState<TabId>(() => {
    const want: TabId | undefined = routeTab === 'disconnections' ? 't351' : routeTab === 'powerblocks' ? 'power' : routeTab === 'caution' ? 'caution' : undefined;
    return want && tabs.includes(want) ? want : tabs[0];
  });
  const [station, setStation] = useState('');
  const [picked, setPicked] = useState<Partial<Record<TabId, string>>>({});
  const [modal, setModal] = useState<{ kind: 'addTsr' } | { kind: 'relax'; tsr: ManualTsr } | { kind: 'withdrawTsr'; tsr: ManualTsr } | { kind: 'withdrawOrder'; order: CautionOrder } | null>(null);

  const day = clamp(drawer.day ?? 0, 0, snapshot.result.weekly.occupancy.length - 1);
  const dayIso = snapshot.result.weekly.occupancy[day]?.date ?? snapshot.planStart;

  const canCaution = can(user, 'issueCaution');
  const canIntake = can(user, 'intake');
  const canDeptAct = can(user, 'execute') || can(user, 'intake');
  const canReceive = canCaution || can(user, 'grant');

  /* ── derived forms ─────────────────────────────────────── */
  const blocks = useMemo(() => workingBlocks(snapshot, approvals), [snapshot, approvals]);
  const blockById = useMemo(() => new Map(blocks.map((b) => [b.id, b])), [blocks]);
  const orders = useMemo(() => cautionOrders(snapshot, blocks, tsrs, forms, day), [snapshot, blocks, tsrs, forms, day]);
  const atStation = (o: CautionOrder) => !station || o.sections.some((i) => corridor.blockSections[i]?.from === station || corridor.blockSections[i]?.to === station);
  const t409 = orders.filter((o) => o.formType === 'T/409' && atStation(o));
  const t409b = orders.filter((o) => o.formType === 'T/409B' && atStation(o));
  const notices = useMemo(() => disconnectionNoticesWeek(snapshot, blocks, forms), [snapshot, blocks, forms]);
  const register = useMemo(() => tsrs.filter((x) => x.corridorId === corridor.id).sort((a, b) => (a.status === 'WITHDRAWN' ? 1 : 0) - (b.status === 'WITHDRAWN' ? 1 : 0)), [tsrs, corridor.id]);
  const powerList = useMemo(() => blocks.filter((b) => b.status !== 'REFUSED' && (b.oheSections.length > 0 || b.kind === 'POWER' || b.kind === 'TRAFFIC + POWER')).sort((a, b) => a.day - b.day || a.start - b.start), [blocks]);
  const clearedBlocks = useMemo(() => new Set(executionLog.filter((r) => r.corridorId === corridor.id && r.status !== 'IN_PROGRESS').map((r) => r.blockId)), [executionLog, corridor.id]);

  /* ── selection per tab (first row when nothing picked) ─── */
  const pick = <T,>(list: T[], key: (x: T) => string): T | null => list.find((x) => key(x) === picked[tab]) ?? list[0] ?? null;
  const selTsr = tab === 'tsr' ? pick(register, (x) => x.id) : null;
  const selOrder = tab === 'caution' ? pick(t409, (x) => x.orderNo) : tab === 'cautionB' ? pick(t409b, (x) => x.orderNo) : tab === 'tsr' && selTsr ? orders.find((o) => o.manual?.id === selTsr.id) ?? null : null;
  const selNotice = tab === 't351' ? pick(notices, (x) => x.noticeNo) : null;
  const selPower = tab === 'power' ? pick(powerList, (x) => x.id) : null;
  const choose = (id: string) => setPicked({ ...picked, [tab]: id });

  /* ── actions ───────────────────────────────────────────── */
  const imposeTsr = (x: ManualTsr) => {
    updateTsr(x.id, { status: 'IN_FORCE' });
    notify({ portals: ['field', 'tms', 'control'], kind: 'CRITICAL', title: t('notifyImposed', { id: x.id }), body: `${kmRange(x.fromKm, x.toKm)} ${x.line} · ${x.kmph} km/h · ${x.reason}`, route: '/app/control/caution' });
    toast({ title: t('toastImposed', { id: x.id }), body: `${kmRange(x.fromKm, x.toKm)} · ${x.kmph} km/h`, tone: 'crit' });
  };
  const issueOrder = (o: CautionOrder) => {
    setFormStatus(o.orderNo, 'ISSUED', `${o.formType} · ${o.section}`);
    toast({ title: t('toastIssued', { form: o.formType, serial: o.orderNo }), tone: 'ok' });
  };
  const noticeStatus = (n: DisconnectionNotice, status: 'ISSUED' | 'RECEIVED' | 'RECONNECTED') => {
    setFormStatus(n.noticeNo, status, `T/351 · ${n.gear}`);
    toast({ title: status === 'ISSUED' ? t('toastIssued', { form: 'T/351', serial: n.noticeNo }) : status === 'RECEIVED' ? t('toastReceived', { serial: n.noticeNo }) : t('toastReconnected', { serial: n.noticeNo }), tone: 'ok' });
  };
  const powerStatus = (b: WorkingBlock, status: 'DEENERGISED' | 'ENERGISED') => {
    setPowerBlock(b.id, status);
    toast({ title: t('toastPower', { id: b.id, state: status === 'DEENERGISED' ? t('powerDeenergised') : t('powerEnergised') }), body: `${b.sectionText} · ${hhmm(b.start)}–${hhmm(b.end)}`, tone: status === 'DEENERGISED' ? 'warn' : 'ok' });
  };

  /* ── columns ───────────────────────────────────────────── */
  const blockBtn = (id: string | null) =>
    id ? (
      <button className="btn btn-sm btn-ghost" onClick={(e) => { e.stopPropagation(); drawer.open('block', id); }}>
        {t('openBlock')}
      </button>
    ) : null;

  const tsrCols: Column<ManualTsr>[] = [
    { key: 'id', header: t('colNo'), render: (x) => <span className="mono strong">{x.id}</span> },
    { key: 'section', header: t('colSection'), render: (x) => <span className="small">{kmRange(x.fromKm, x.toKm)} · {x.line}</span> },
    { key: 'speed', header: t('colSpeed'), render: (x) => <span className="num strong">{x.kmph} km/h</span> },
    {
      key: 'status',
      header: t('colStatus'),
      render: (x) => (
        <div className="row-wrap" style={{ gap: 4 }}>
          <StatusBadge status={x.status} />
          {x.relaxationRequested && x.status !== 'WITHDRAWN' && <Badge tone="info" title={x.relaxationRequested.note}>{t('relaxRequested')}</Badge>}
        </div>
      ),
    },
    { key: 'reason', header: t('colReason'), hideMobile: true, render: (x) => <span className="small truncate" style={{ display: 'inline-block', maxWidth: 220 }} title={x.reason}>{x.reason}</span> },
    { key: 'since', header: t('colSince'), hideMobile: true, render: (x) => <span className="small muted">{timeAgo(x.since)} → {x.until ?? t('untilCancelled')}</span> },
    { key: 'loss', header: t('colLoss'), num: true, hideMobile: true, render: (x) => (x.taskId && snapshot.tsrLossPerDay[x.taskId] !== undefined ? <span className="num">{num(snapshot.tsrLossPerDay[x.taskId])}</span> : <span className="muted">{t('none')}</span>) },
    {
      key: 'actions',
      header: t('colActions'),
      render: (x) => {
        const out: ReactNode[] = [];
        if (role === 'control' && x.status === 'PROPOSED') out.push(<button key="imp" className="btn btn-sm btn-primary" disabled={!canCaution} title={canCaution ? undefined : t('noCaution')} onClick={(e) => { e.stopPropagation(); imposeTsr(x); }}>{t('impose')}</button>);
        if (role === 'control' && x.status === 'IN_FORCE') {
          const ok = !!x.relaxationRequested || (!!x.blockId && clearedBlocks.has(x.blockId));
          out.push(<button key="wd" className="btn btn-sm" disabled={!canCaution || !ok} title={!canCaution ? t('noCaution') : ok ? undefined : t('withdrawNeeds')} onClick={(e) => { e.stopPropagation(); setModal({ kind: 'withdrawTsr', tsr: x }); }}>{t('withdraw')}</button>);
        }
        if (role === 'tms' && x.status === 'IN_FORCE' && !x.relaxationRequested) out.push(<button key="rx" className="btn btn-sm" disabled={!canIntake} title={canIntake ? undefined : t('noIntake')} onClick={(e) => { e.stopPropagation(); setModal({ kind: 'relax', tsr: x }); }}>{t('relax')}</button>);
        out.push(blockBtn(x.blockId ?? null));
        return <div className="row" style={{ gap: 6, justifyContent: 'flex-end' }}>{out}</div>;
      },
    },
  ];

  const orderCols: Column<CautionOrder>[] = [
    { key: 'no', header: t('colNo'), render: (o) => <span className="mono small strong">{o.orderNo}</span> },
    { key: 'section', header: t('colSection'), render: (o) => <div><div className="small strong">{o.section}</div><div className="tiny muted">{kmRange(o.startKm, o.endKm)} · {o.line}</div></div> },
    { key: 'speed', header: t('colSpeed'), render: (o) => <div><span className="num strong">{o.speedKmph} km/h</span><div className="tiny muted">{t('normalSpeed', { v: o.normalSpeedKmph })}</div></div> },
    { key: 'valid', header: t('colValid'), hideMobile: true, render: (o) => <span className="small mono">{o.validFrom} → {o.validTo}</span> },
    { key: 'reason', header: t('colReason'), hideMobile: true, render: (o) => <span className="small truncate" style={{ display: 'inline-block', maxWidth: 220 }} title={o.reason}>{o.reason}</span> },
    { key: 'status', header: t('colStatus'), render: (o) => <StatusBadge status={o.status} /> },
    {
      key: 'actions',
      header: t('colActions'),
      render: (o) => {
        const proposed = o.manual?.status === 'PROPOSED';
        return (
          <div className="row" style={{ gap: 6, justifyContent: 'flex-end' }}>
            {role === 'control' && o.status === 'DRAFT' && (
              <button className="btn btn-sm btn-primary" disabled={!canCaution || proposed} title={!canCaution ? t('noCaution') : proposed ? t('issueProposed') : undefined} onClick={(e) => { e.stopPropagation(); issueOrder(o); }}>
                {t('issue')}
              </button>
            )}
            {role === 'control' && o.status === 'ISSUED' && (
              <button className="btn btn-sm" disabled={!canCaution} title={canCaution ? undefined : t('noCaution')} onClick={(e) => { e.stopPropagation(); setModal({ kind: 'withdrawOrder', order: o }); }}>
                {t('withdraw')}
              </button>
            )}
            {blockBtn(o.liftingBlockId)}
          </div>
        );
      },
    },
  ];

  const noticeCols: Column<DisconnectionNotice>[] = [
    { key: 'no', header: t('colNo'), render: (n) => <span className="mono small strong">{n.noticeNo}</span> },
    { key: 'block', header: t('colBlock'), render: (n) => { const b = blockById.get(n.blockId); return <div><div className="small mono">{n.blockId}</div>{b && <div className="tiny muted">{dateLabel(b.date)} · {b.sectionText}</div>}</div>; } },
    { key: 'gear', header: t('colGear'), hideMobile: true, render: (n) => <span className="small">{n.gear}</span> },
    { key: 'time', header: t('colTime'), render: (n) => <span className="small mono">{n.disconnectionTime} → {n.reconnectionTime}</span> },
    { key: 'status', header: t('colStatus'), render: (n) => <StatusBadge status={n.status} /> },
    {
      key: 'actions',
      header: t('colActions'),
      render: (n) => (
        <div className="row" style={{ gap: 6, justifyContent: 'flex-end' }}>
          {role === 'smms' && n.status === 'DRAFT' && <button className="btn btn-sm btn-primary" disabled={!canDeptAct} title={canDeptAct ? undefined : t('noDeptCap')} onClick={(e) => { e.stopPropagation(); noticeStatus(n, 'ISSUED'); }}>{t('issue')}</button>}
          {role === 'control' && n.status === 'ISSUED' && <button className="btn btn-sm btn-primary" disabled={!canReceive} title={canReceive ? undefined : t('noCaution')} onClick={(e) => { e.stopPropagation(); noticeStatus(n, 'RECEIVED'); }}>{t('markReceived')}</button>}
          {role === 'smms' && (n.status === 'ISSUED' || n.status === 'RECEIVED') && <button className="btn btn-sm" disabled={!canDeptAct} title={canDeptAct ? undefined : t('noDeptCap')} onClick={(e) => { e.stopPropagation(); noticeStatus(n, 'RECONNECTED'); }}>{t('markReconnected')}</button>}
          {blockBtn(n.blockId)}
        </div>
      ),
    },
  ];

  const powerCols: Column<WorkingBlock>[] = [
    { key: 'block', header: t('colBlock'), render: (b) => <div><div className="small mono strong">{b.id}</div><div className="tiny muted">{dateLabel(b.date)} · {hhmm(b.start)}–{hhmm(b.end)}</div></div> },
    { key: 'section', header: t('colSection'), render: (b) => <span className="small">{b.sectionText} · {b.line}</span> },
    { key: 'ohe', header: t('colOhe'), hideMobile: true, render: (b) => <span className="small">{b.oheSections.length ? b.oheSections.map((s) => s.label).join(', ') : t('none')}</span> },
    {
      key: 'status',
      header: t('colStatus'),
      render: (b) => {
        const rec = powerBlocks[b.id];
        const st = rec?.status ?? 'PENDING';
        return (
          <div>
            <Badge tone={st === 'DEENERGISED' ? 'warn' : st === 'ENERGISED' ? 'ok' : 'gray'}>{st === 'DEENERGISED' ? t('powerDeenergised') : st === 'ENERGISED' ? t('powerEnergised') : t('powerPending')}</Badge>
            {rec && <div className="tiny muted">{t('recordedBy', { by: rec.by, when: timeAgo(rec.at) })}</div>}
          </div>
        );
      },
    },
    {
      key: 'actions',
      header: t('colActions'),
      render: (b) => {
        const st = powerBlocks[b.id]?.status ?? 'PENDING';
        return (
          <div className="row" style={{ gap: 6, justifyContent: 'flex-end' }}>
            {st !== 'DEENERGISED' && <button className="btn btn-sm btn-primary" disabled={!canDeptAct} title={canDeptAct ? undefined : t('noDeptCap')} onClick={(e) => { e.stopPropagation(); powerStatus(b, 'DEENERGISED'); }}>{t('deenergise')}</button>}
            {st === 'DEENERGISED' && <button className="btn btn-sm btn-ok" disabled={!canDeptAct} title={canDeptAct ? undefined : t('noDeptCap')} onClick={(e) => { e.stopPropagation(); powerStatus(b, 'ENERGISED'); }}>{t('energise')}</button>}
            {blockBtn(b.id)}
          </div>
        );
      },
    },
  ];

  /* ── stats ─────────────────────────────────────────────── */
  const inForce = register.filter((x) => x.status === 'IN_FORCE');
  const dayOrders = [...orders.filter((o) => o.formType === 'T/409'), ...orders.filter((o) => o.formType === 'T/409B')];
  const tiles: ReactNode[] = [];
  if (tabs.includes('tsr')) tiles.push(<StatTile key="tsr" icon={<ShieldAlert size={14} />} label={t('statTsr')} value={inForce.length} sub={t('statTsrSub', { p: register.filter((x) => x.status === 'PROPOSED').length, r: inForce.filter((x) => x.relaxationRequested).length })} />);
  if (tabs.includes('caution')) tiles.push(<StatTile key="ord" icon={<FileText size={14} />} label={t('statOrders', { date: dateLabel(dayIso) })} value={dayOrders.length} sub={t('statOrdersSub', { issued: dayOrders.filter((o) => o.status === 'ISSUED').length, draft: dayOrders.filter((o) => o.status === 'DRAFT').length })} />);
  if (tabs.includes('t351')) tiles.push(<StatTile key="t351" icon={<Wrench size={14} />} label={t('statT351')} value={notices.length} sub={t('statT351Sub', { open: notices.filter((n) => n.status !== 'RECEIVED' && n.status !== 'RECONNECTED').length })} />);
  if (tabs.includes('power')) tiles.push(<StatTile key="pw" icon={<Zap size={14} />} label={t('statPower')} value={powerList.length} sub={t('statPowerSub', { n: powerList.filter((b) => powerBlocks[b.id]?.status === 'DEENERGISED').length })} />);

  const tabLabel: Record<TabId, Key> = { tsr: 'tabTsr', caution: 'tabCaution', cautionB: 'tabCautionB', t351: 'tabT351', power: 'tabPower' };
  const tabCount: Record<TabId, number> = { tsr: register.length, caution: t409.length, cautionB: t409b.length, t351: notices.length, power: powerList.length };
  const lede = role === 'tms' ? t('ledeTms') : role === 'smms' ? t('ledeSmms') : role === 'tdms' ? t('ledeTdms') : t('ledeControl');
  const showDay = tab === 'caution' || tab === 'cautionB';

  let table: ReactNode = null;
  if (tab === 'tsr') table = <DataTable<ManualTsr> columns={tsrCols} rows={register} rowKey={(x) => x.id} onRowClick={(x) => choose(x.id)} selectedKey={selTsr?.id} empty={t('emptyTsr')} />;
  else if (tab === 'caution') table = <div data-tour="caution-orders"><DataTable<CautionOrder> columns={orderCols} rows={t409} rowKey={(o) => o.orderNo} onRowClick={(o) => choose(o.orderNo)} selectedKey={selOrder?.orderNo} empty={t('emptyCaution', { date: dateLabel(dayIso) })} /></div>;
  else if (tab === 'cautionB') table = <div data-tour="caution-orders"><DataTable<CautionOrder> columns={orderCols} rows={t409b} rowKey={(o) => o.orderNo} onRowClick={(o) => choose(o.orderNo)} selectedKey={selOrder?.orderNo} empty={t('emptyCautionB', { date: dateLabel(dayIso) })} /></div>;
  else if (tab === 't351') table = <DataTable<DisconnectionNotice> columns={noticeCols} rows={notices} rowKey={(n) => n.noticeNo} onRowClick={(n) => choose(n.noticeNo)} selectedKey={selNotice?.noticeNo} empty={t('emptyT351')} />;
  else table = <DataTable<WorkingBlock> columns={powerCols} rows={powerList} rowKey={(b) => b.id} onRowClick={(b) => choose(b.id)} selectedKey={selPower?.id} empty={t('emptyPower')} />;

  let sheet: ReactNode = null;
  if (selOrder) sheet = <CautionSheet order={selOrder} dayIso={dayIso} division={corridor.division} record={forms[selOrder.orderNo]} />;
  else if (selNotice) sheet = <NoticeSheet notice={selNotice} block={blockById.get(selNotice.blockId) ?? null} />;
  else if (selPower) sheet = <IsolationSheet block={selPower} record={powerBlocks[selPower.id]} towerWagons={selPower.machines.map((id) => snapshot.feeds.machines.find((m) => m.id === id)).filter((m) => m?.type === 'TOWER_WAGON').map((m) => m?.label ?? '')} />;

  return (
    <div className="stack-lg">
      <PageHeader
        title={t('title')}
        lede={lede}
        badges={<span className="tiny muted">{t('nomenclature')}</span>}
        actions={
          role === 'control' ? (
            <button className="btn btn-primary btn-sm" disabled={!canCaution} title={canCaution ? undefined : t('noCaution')} onClick={() => setModal({ kind: 'addTsr' })}>
              <PlusCircle size={14} /> {t('addTsr')}
            </button>
          ) : role === 'tms' ? (
            <button className="btn btn-primary btn-sm" disabled={!canIntake} title={canIntake ? undefined : t('noIntake')} onClick={() => setModal({ kind: 'addTsr' })}>
              <PlusCircle size={14} /> {t('proposeTsr')}
            </button>
          ) : undefined
        }
      />

      <div className="grid grid-auto">{tiles}</div>

      {tabs.length > 1 && <Tabs<TabId> tabs={tabs.map((id) => ({ id, label: t(tabLabel[id]), count: tabCount[id] }))} value={tab} onChange={setTab} />}

      <div className="grid grid-main-aside" style={{ alignItems: 'start' }}>
        <Card>
          <CardHead
            title={t(tabLabel[tab])}
            right={
              tab === 'tsr' ? (
                <SimLabel kind="localOnly" />
              ) : showDay ? (
                <SimLabel kind="seededFeed" system="TMS" />
              ) : tab === 'power' ? (
                <span className="tiny muted">{t('tpcNote')}</span>
              ) : undefined
            }
          />
          {showDay && (
            <CardBody tight>
              <div className="form-grid">
                <Field label={t('planDay')}>
                  <select className="select" value={day} onChange={(e) => drawer.set('day', Number(e.target.value) || null)}>
                    {snapshot.result.weekly.occupancy.map((o) => <option key={o.day} value={o.day}>{dateLabel(o.date)}</option>)}
                  </select>
                </Field>
                <Field label={t('station')}>
                  <select className="select" value={station} onChange={(e) => setStation(e.target.value)}>
                    <option value="">{t('allStations')}</option>
                    {corridor.stations.map((s) => <option key={s.code} value={s.code}>{s.code} · {s.name}</option>)}
                  </select>
                </Field>
              </div>
            </CardBody>
          )}
          <CardBody flush>{table}</CardBody>
        </Card>

        <Card>
          <CardHead title={t('previewTitle')} right={sheet ? <PrintButton label={t('print')} targetId="forms-sheet" /> : undefined} />
          <CardBody>{sheet ?? <EmptyState title={t('previewEmpty')} />}</CardBody>
        </Card>
      </div>

      {modal?.kind === 'addTsr' && <TsrModal mode={role === 'control' ? 'add' : 'propose'} snapshot={snapshot} onClose={() => setModal(null)} />}
      {modal?.kind === 'relax' && <RelaxModal tsr={modal.tsr} mps={corridor.mpsKmph} onClose={() => setModal(null)} />}
      {modal?.kind === 'withdrawTsr' && (
        <ReasonModal
          title={t('withdrawTsrTitle', { id: modal.tsr.id })}
          onClose={() => setModal(null)}
          onConfirm={(reason) => {
            const x = modal.tsr;
            updateTsr(x.id, { status: 'WITHDRAWN' });
            notify({ portals: ['field', 'tms', 'control'], kind: 'OK', title: t('notifyWithdrawn', { id: x.id }), body: reason, route: '/app/control/caution' });
            toast({ title: t('toastWithdrawn', { id: x.id }), body: reason, tone: 'ok' });
            setModal(null);
          }}
        />
      )}
      {modal?.kind === 'withdrawOrder' && (
        <ReasonModal
          title={t('withdrawOrderTitle', { id: modal.order.orderNo })}
          onClose={() => setModal(null)}
          onConfirm={(reason) => {
            setFormStatus(modal.order.orderNo, 'WITHDRAWN', reason);
            toast({ title: t('toastOrderWithdrawn', { serial: modal.order.orderNo }), body: reason, tone: 'info' });
            setModal(null);
          }}
        />
      )}

      <BlockDrawer blockId={drawer.blockId} onClose={() => drawer.close('block')} />
      <TaskDrawer taskId={drawer.taskId} onClose={() => drawer.close('task')} />
    </div>
  );
}

/* ── Printable sheets ──────────────────────────────────────── */
function CautionSheet({ order, dayIso, division, record }: { order: CautionOrder; dayIso: string; division: string; record?: { status: string; by: string; at: string } }) {
  const t = useT(strings);
  return (
    <FormSheet id="forms-sheet" title={order.formTitle} formNo={order.orderNo}>
      <div style={sheetRow}>
        <span><b>{t('sheetDivision')}:</b> {division}</span>
        <span><b>{t('sheetDate')}:</b> {dateLong(dayIso)}</span>
      </div>
      <div style={{ fontSize: 12 }}><b>{t('sheetTo')}:</b> {t('sheetToCaution')}</div>
      <table style={sheetTable}>
        <thead>
          <tr>
            <th style={sheetCell}>{t('sheetBetween')}</th>
            <th style={sheetCell}>{t('sheetLine')}</th>
            <th style={sheetCell}>{t('sheetCautionSpeed')}</th>
            <th style={sheetCell}>{t('sheetNormal')}</th>
            <th style={sheetCell}>{t('sheetReason')}</th>
            <th style={sheetCell}>{t('sheetValid')}</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td style={sheetCell}><b>{order.section}</b><br />{kmRange(order.startKm, order.endKm)}</td>
            <td style={sheetCell}>{lineLabel(order.line)}</td>
            <td style={sheetCell}><b>{order.speedKmph} km/h</b></td>
            <td style={sheetCell}>{order.normalSpeedKmph} km/h</td>
            <td style={sheetCell}>{order.reason}</td>
            <td style={sheetCell}>{order.validFrom} → {order.validTo}</td>
          </tr>
        </tbody>
      </table>
      {order.affectedTrains.length > 0 && (
        <div style={{ fontSize: 11 }}><b>{t('sheetTrains')}:</b> {order.affectedTrains.map((x) => x.trainNo).join(', ')}</div>
      )}
      <div style={{ ...sheetRow, marginTop: 10 }}>
        <span><b>{t('sheetIssuedBy')}:</b> {order.issuedBy}</span>
        <span><b>{t('sheetStatus')}:</b> {t(`fs_${order.status}` as Key)}{record ? ` · ${record.by} · ${timeAgo(record.at)}` : ''}</span>
      </div>
      <div style={signGrid}>
        <div style={signLine}>{t('sheetSm')}</div>
        <div style={signLine}>{t('sheetSc')}</div>
      </div>
    </FormSheet>
  );
}

function NoticeSheet({ notice, block }: { notice: DisconnectionNotice; block: WorkingBlock | null }) {
  const t = useT(strings);
  const section = notice.section || block?.sectionText || t('none');
  return (
    <FormSheet id="forms-sheet" title={notice.formTitle} formNo={notice.noticeNo}>
      <div style={sheetRow}>
        <span><b>{t('sheetBlock')}:</b> {notice.blockId}</span>
        <span><b>{t('sheetDate')}:</b> {block ? dateLong(block.date) : t('none')}</span>
      </div>
      <div style={{ fontSize: 12 }}><b>{t('sheetTo')}:</b> {t('sheetToNotice', { section })}</div>
      <table style={sheetTable}>
        <tbody>
          <tr><th style={sheetCell}>{t('sheetGear')}</th><td style={sheetCell}>{notice.gear} · {kmRange(notice.startKm, notice.endKm)}</td></tr>
          <tr><th style={sheetCell}>{t('sheetDisconnect')}</th><td style={sheetCell}>{notice.disconnectionTime}</td></tr>
          <tr><th style={sheetCell}>{t('sheetReconnect')}</th><td style={sheetCell}>{notice.reconnectionTime}</td></tr>
          <tr><th style={sheetCell}>{t('sheetSafety')}</th><td style={sheetCell}>{notice.safetyAssurance}</td></tr>
          <tr><th style={sheetCell}>{t('sheetIncharge')}</th><td style={sheetCell}>{block?.approval?.incharge ?? notice.inCharge}</td></tr>
          <tr><th style={sheetCell}>{t('sheetStatus')}</th><td style={sheetCell}>{t(`fs_${notice.status}` as Key)}</td></tr>
        </tbody>
      </table>
      <div style={signGrid}>
        <div style={signLine}>{t('sheetSse')}</div>
        <div style={signLine}>{t('sheetSm')}</div>
      </div>
    </FormSheet>
  );
}

function IsolationSheet({ block, record, towerWagons }: { block: WorkingBlock; record?: { status: string; by: string; at: string }; towerWagons: string[] }) {
  const t = useT(strings);
  const st = record?.status ?? 'PENDING';
  return (
    <FormSheet id="forms-sheet" title={t('sheetPowerTitle')} formNo={block.id}>
      <div style={sheetRow}>
        <span><b>{t('sheetDate')}:</b> {dateLong(block.date)}</span>
        <span><b>{t('sheetWindow')}:</b> {hhmm(block.start)}–{hhmm(block.end)}</span>
      </div>
      <div style={{ fontSize: 12 }}>{block.sectionText} · {lineLabel(block.line)} · {kmRange(block.startKm, block.endKm)}</div>
      <div style={{ fontSize: 12, marginTop: 10 }}><b>{t('sheetIsolation')}</b></div>
      <table style={sheetTable}>
        <thead>
          <tr>
            <th style={sheetCell}>{t('colOhe')}</th>
            <th style={sheetCell}>{t('sheetSp')}</th>
            <th style={sheetCell}>km</th>
          </tr>
        </thead>
        <tbody>
          {block.oheSections.map((s) => (
            <tr key={s.id}>
              <td style={sheetCell}>{s.label}</td>
              <td style={sheetCell}>{s.spFrom} → {s.spTo}</td>
              <td style={sheetCell}>{kmRange(s.startKm, s.endKm)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table style={sheetTable}>
        <tbody>
          <tr><th style={sheetCell}>{t('sheetTpc')}</th><td style={sheetCell}>{st === 'DEENERGISED' ? t('powerDeenergised') : st === 'ENERGISED' ? t('powerEnergised') : t('powerPending')}{record ? ` · ${record.by} · ${timeAgo(record.at)}` : ''}</td></tr>
          <tr><th style={sheetCell}>{t('sheetTower')}</th><td style={sheetCell}>{towerWagons.length ? towerWagons.join(', ') : t('none')}</td></tr>
          <tr><th style={sheetCell}>{t('sheetIncharge')}</th><td style={sheetCell}>{block.approval?.incharge ?? t('none')}</td></tr>
        </tbody>
      </table>
      <div style={{ fontSize: 10 }}>{t('tpcNote')}</div>
      <div style={signGrid}>
        <div style={signLine}>{t('sheetTrd')}</div>
        <div style={signLine}>{t('sheetTpcSign')}</div>
      </div>
    </FormSheet>
  );
}

/* ── Modals ────────────────────────────────────────────────── */
function TsrModal({ mode, snapshot, onClose }: { mode: 'add' | 'propose'; snapshot: Snapshot; onClose: () => void }) {
  const t = useT(strings);
  const user = useAppStore((s) => s.user);
  const addTsr = useAppStore((s) => s.addTsr);
  const addIntakeTask = useAppStore((s) => s.addIntakeTask);
  const runPlan = useAppStore((s) => s.runPlan);
  const toast = useAppStore((s) => s.toast);
  const corridor = snapshot.corridor;

  const [line, setLine] = useState<Line>('UP');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [speed, setSpeed] = useState('');
  const [reason, setReason] = useState('');
  const [inject, setInject] = useState(false);
  const [workType, setWorkType] = useState('');

  const a = Number(from);
  const b = Number(to);
  const v = Number(speed);
  const kmErr = from.trim() === '' || to.trim() === '' || !Number.isFinite(a) || !Number.isFinite(b) || a < 0 || b > corridor.lengthKm || a > b;
  const speedErr = speed.trim() === '' || !Number.isFinite(v) || v <= 0 || v >= corridor.mpsKmph;
  const reasonErr = !reason.trim();
  const workErr = mode === 'add' && inject && !workType;
  const blocked = kmErr || speedErr || reasonErr || workErr;
  const touched = from !== '' || to !== '';

  const confirm = () => {
    const tsr = addTsr({ corridorId: corridor.id, line, fromKm: a, toKm: b, kmph: v, reason: reason.trim(), status: mode === 'add' ? 'IN_FORCE' : 'PROPOSED' });
    toast({ title: mode === 'add' ? t('toastTsrInForce', { a: a.toFixed(1), b: b.toFixed(1), v }) : t('toastTsrProposed', { a: a.toFixed(1), b: b.toFixed(1), v }), body: tsr.id, tone: mode === 'add' ? 'crit' : 'info' });
    if (mode === 'add' && inject && WT[workType]) {
      const wt = WT[workType];
      addIntakeTask({ spec: { sourceId: `TSR/${tsr.id}`, label: `${wt.label} — ${tsr.id}`, workType, line, startKm: a, endKm: b, tsrKmph: v, daysOverdue: 0, note: reason.trim() }, label: `${wt.label} · ${kmRange(a, b)} ${line}`, dept: wt.dept, submittedBy: user?.name ?? 'Control', role: user?.role ?? 'UNKNOWN', source: 'EMERGENCY-TSR' });
      void runPlan({ reason: t('replanReason', { id: tsr.id }) });
      toast({ title: t('toastInjected'), body: wt.label, tone: 'info' });
    }
    onClose();
  };

  return (
    <Modal
      open
      onClose={onClose}
      title={mode === 'add' ? t('tsrTitleAdd') : t('tsrTitlePropose')}
      width={560}
      footer={
        <div className="row" style={{ justifyContent: 'flex-end', width: '100%' }}>
          <button className="btn" onClick={onClose}>{t('cancel')}</button>
          <button className="btn btn-primary" disabled={blocked} onClick={confirm}>{t('confirm')}</button>
        </div>
      }
    >
      <div className="stack">
        <div className="small muted">{mode === 'add' ? t('tsrBodyAdd') : t('tsrBodyPropose')}</div>
        <div className="grid grid-3" style={{ gap: 10 }}>
          <Field label={t('fFrom')}>
            <input className="input" type="number" step={0.1} value={from} onChange={(e) => setFrom(e.target.value)} />
          </Field>
          <Field label={t('fTo')}>
            <input className="input" type="number" step={0.1} value={to} onChange={(e) => setTo(e.target.value)} />
          </Field>
          <Field label={t('fLine')}>
            <select className="select" value={line} onChange={(e) => setLine(e.target.value as Line)}>
              <option value="UP">{t('lineUp')}</option>
              <option value="DN">{t('lineDn')}</option>
              <option value="BOTH">{t('lineBoth')}</option>
            </select>
          </Field>
        </div>
        {kmErr && touched && <div className="small" style={{ color: 'var(--crit)' }}>{t('errKm', { len: corridor.lengthKm })}</div>}
        <Field label={t('fSpeed')} error={speedErr && speed !== '' ? t('errSpeed', { mps: corridor.mpsKmph }) : undefined}>
          <input className="input" type="number" min={1} max={corridor.mpsKmph - 1} step={5} value={speed} onChange={(e) => setSpeed(e.target.value)} />
        </Field>
        <Field label={t('fReason')} error={reasonErr && reason !== '' ? t('errReason') : undefined}>
          <input className="input" value={reason} onChange={(e) => setReason(e.target.value)} />
        </Field>
        {mode === 'add' && (
          <>
            <label className="check">
              <input type="checkbox" checked={inject} onChange={(e) => setInject(e.target.checked)} /> {t('fInject')}
            </label>
            {inject && (
              <Field label={t('fWork')} error={workErr ? t('errWork') : undefined}>
                <select className="select" value={workType} onChange={(e) => setWorkType(e.target.value)}>
                  <option value="">{t('fWorkPick')}</option>
                  {Object.entries(WT).map(([k, d]) => <option key={k} value={k}>{d.label} · {d.dept}</option>)}
                </select>
              </Field>
            )}
          </>
        )}
      </div>
    </Modal>
  );
}

function RelaxModal({ tsr, mps, onClose }: { tsr: ManualTsr; mps: number; onClose: () => void }) {
  const t = useT(strings);
  const user = useAppStore((s) => s.user);
  const updateTsr = useAppStore((s) => s.updateTsr);
  const notify = useAppStore((s) => s.notify);
  const toast = useAppStore((s) => s.toast);
  const [speed, setSpeed] = useState('');
  const [note, setNote] = useState('');
  const v = Number(speed);
  const bad = speed.trim() === '' || !Number.isFinite(v) || v <= tsr.kmph || v >= mps;
  return (
    <Modal
      open
      onClose={onClose}
      title={t('relaxTitle', { id: tsr.id })}
      footer={
        <div className="row" style={{ justifyContent: 'flex-end', width: '100%' }}>
          <button className="btn" onClick={onClose}>{t('cancel')}</button>
          <button
            className="btn btn-primary"
            disabled={bad}
            onClick={() => {
              const text = t('relaxNoteText', { v, note: note.trim() || '—' });
              updateTsr(tsr.id, { relaxationRequested: { by: user?.name ?? 'Unknown', at: new Date().toISOString(), note: text } });
              notify({ portals: ['control'], kind: 'ACTION', title: t('notifyRelax', { id: tsr.id }), body: text, route: '/app/control/caution' });
              toast({ title: t('toastRelax', { id: tsr.id }), body: text, tone: 'ok' });
              onClose();
            }}
          >
            {t('confirm')}
          </button>
        </div>
      }
    >
      <div className="stack">
        <div className="small muted">{t('relaxBody')}</div>
        <div className="small">{kmRange(tsr.fromKm, tsr.toKm)} · {tsr.line} · {tsr.kmph} km/h · {tsr.reason}</div>
        <Field label={t('relaxSpeed')} error={bad && speed !== '' ? t('errRelax', { v: tsr.kmph, mps }) : undefined}>
          <input className="input" type="number" min={tsr.kmph + 1} max={mps - 1} step={5} value={speed} onChange={(e) => setSpeed(e.target.value)} />
        </Field>
        <Field label={t('relaxNote')}>
          <textarea className="textarea" rows={3} value={note} onChange={(e) => setNote(e.target.value)} />
        </Field>
      </div>
    </Modal>
  );
}

function ReasonModal({ title, onClose, onConfirm }: { title: string; onClose: () => void; onConfirm: (reason: string) => void }) {
  const t = useT(strings);
  const [reason, setReason] = useState('');
  const empty = !reason.trim();
  return (
    <Modal
      open
      onClose={onClose}
      title={title}
      footer={
        <div className="row" style={{ justifyContent: 'flex-end', width: '100%' }}>
          <button className="btn" onClick={onClose}>{t('cancel')}</button>
          <button className="btn btn-danger" disabled={empty} title={empty ? t('errReason') : undefined} onClick={() => onConfirm(reason.trim())}>{t('withdraw')}</button>
        </div>
      }
    >
      <Field label={t('withdrawReason')} error={empty ? t('errReason') : undefined}>
        <textarea className="textarea" rows={3} value={reason} onChange={(e) => setReason(e.target.value)} />
      </Field>
    </Modal>
  );
}
